import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { peopleKey } from '../people/people';

/** A member of a pool: a person (`personId`, `name`) or another pool (`pool`, its name; `personId` null), the `share` percent (two decimals; a JSON number, shown with two), and whether they are `retired` (a retirement
 *  date set, whatever the date): then their share counts as 0.00 toward the pool's total. `cut` is their cut of the sheet's
 *  pool's pot (two decimals, as text; a retired member's 0.00), null when the pool is not balanced or has no pot: a pool that
 *  is a member of none has the sheet's pot, a member pool its cut in the pool above. */
export type PoolMember = { personId: number | null; name: string; pool: string | null; share: number; retired: boolean; cut: string | null };

/** A pool of the sheet: its `name` (trimmed, unique on the sheet), its members in the order added, the `totalShare`
 *  of their shares, and whether it is `balanced` (a total of exactly 100.00). A person can be in several pools. */
export type Pool = { name: string; members: PoolMember[]; totalShare: number; balanced: boolean };

/** Under the people's key, so every change to a person (a retirement above all) reloads the totals. */
export const poolsKey = (sheetId: string) => [...peopleKey(sheetId), 'pools'];

/** The sheet's pools, in the order added. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { usePeople } from '../people/people';
import { poolsKey, usePools, type Pool, type PoolMember } from './pools';

/** One pool: its total share and whether it is balanced, each member's line with their share, and the picker that adds
 *  a person, or another pool (pool:<name>), with a share. A pool already a member of a pool, one that would contain
 *  itself through any chain, or a chain of pools more than three deep is refused too. A person already in the pool, or a share not more than 0.00 and at most 100.00 with two
 *  decimals, is refused with the pool's error. */
function PoolRow({ sheetId, user, pool, pools }: { sheetId: string; user: string; pool: Pool; pools: Pool[] }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');
  const [share, setShare] = useState('');

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (m: { personId: number | null; memberPool: string | null; share: string }) =>
      postJson<PoolMember>(`/api/sheets/${encodeURIComponent(sheetId)}/pools/members`, { pool: pool.name, ...m, by: user }),
    onSuccess: async () => {
      setChosen('');
      setShare('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total <span data-testid="pool-total-share">{pool.totalShare.toFixed(2)}</span>, balanced{' '}
      <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li
            key={m.pool === null ? m.personId : `pool-${m.pool}`}
            data-testid={m.pool === null ? `pool-member-${pool.name}-${m.personId}` : `pool-member-${pool.name}-pool-${m.pool}`}
          >
            {m.pool === null ? m.name : `pool:${m.pool}`}: <span data-testid="pool-share">{m.share.toFixed(2)}</span>, cut{' '}
            <span data-testid="pool-cut">{m.cut ?? ''}</span>
            {m.retired && ' (retired)'}
          </li>
        ))}
      </ul>
      <select
        data-testid="pool-member-select"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          add.reset();
        }}
      >
        <option value="">Person…</option>
        {(people.data ?? []).map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
        {pools.map((p) => (
          <option key={`pool:${p.name}`} value={`pool:${p.name}`}>
            {`pool:${p.name}`}
          </option>
        ))}
      </select>{' '}
      <input
        data-testid="pool-member-share"
        placeholder="Share %"
        value={share}
        onChange={(e) => {
          setShare(e.target.value);
          add.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="pool-member-add"
        disabled={add.isPending}
        onClick={() => {
          if (!submit.begin()) return;
          add.reset();
          // nothing chosen: no person 0, so the server refuses it
          if (chosen.startsWith('pool:')) add.mutate({ personId: null, memberPool: chosen.slice('pool:'.length), share });
          else add.mutate({ personId: Number(chosen), memberPool: null, share });
        }}
      >
        Add member
      </button>
      {add.isError && <span data-testid="pool-error"> Could not add this member.</span>}
    </li>
  );
}

/** The sheet's pools: the form that adds one (its name trimmed, not blank, not already taken), and each pool's row. */
function Pools({ sheetId, user }: { sheetId: string; user: string }) {
  const pools = usePools(sheetId);
  const queryClient = useQueryClient();
  const [name, setName] = useState('');

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (n: string) => postJson<Pool>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`, { name: n, by: user }),
    onSuccess: async () => {
      setName('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <section data-testid="pools">
      <h3>Pools</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          add.reset();
          add.mutate(name);
        }}
      >
        <input
          data-testid="pool-form-name"
          placeholder="Pool name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {add.isError && <span data-testid="pool-form-error"> A pool's name must not be blank nor already taken.</span>}
      </form>
      {pools.isError && <p data-testid="pools-load-error">Could not load pools.</p>}
      <ul>
        {(pools.data ?? []).map((p) => (
          <PoolRow key={p.name} sheetId={sheetId} user={user} pool={p} pools={pools.data ?? []} />
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 9.7, Component: Pools });
