      </label>{' '}
      <button type="submit" data-testid="rate-preview">
        Preview
      </button>
      {result !== null && (
        <span>
          {' '}Claims changed <span data-testid="rate-preview-count">{result.count}</span>
          {' '}Difference <span data-testid="rate-preview-diff">{result.diff}</span>
